dest_csv = Path("data/investigation.csv")
lines = [l.strip() for l in TSV_DATA.strip().split("\n") if l.strip()]
reader = csv.reader(lines, delimiter="\t")
with open(dest_csv, "w", newline="", encoding="utf-8-sig") as f:
    writer = csv.writer(f)
    for row in reader:
        writer.writerow(row)

print(f"Successfully generated updated {dest_csv} with {len(lines)} rows.")
